 let operation=AppOperationContext{app_instance_id:4,parent_document_id:"original-layout".into(),operation_id:71,generation:3,canonical_base_revision:[31;32],retained:generous(),authoring_seed:"original-fixture".into()};let parent_identity=parent.borrow().reference_identity().2;let(mut lookup,_)=OriginalChildMemberLookup::admit(generous()).unwrap();let read=loop{let step=READ.read_original(parent.borrow(),&view,key.borrowed(),&operation,&mut lookup,generous()).unwrap();if let Some(read)=step.read{break read}};assert_eq!(&*read.read as*const String,Arc::as_ptr(&payload));let(mut read_cursor,_)=ChildVectorReadCursor::admit(generous()).unwrap();let read_stamp=loop{let source=erase_child_admission_source(parent.borrow(),7);let d=read_cursor.next_demand(source,&LENDER,1,&read,&READ.identity).unwrap();let step=READ.qualify(source,&LENDER,1,&read,&mut read_cursor,exact(d)).unwrap();if let Some(stamp)=step.stamp{break stamp}};
